export const router = {
  postHandlers: [] as { path: string; handler: (req: any, res: any) => void }[],
  getHandlers: [] as { path: string; handler: (req: any, res: any) => void }[],
  putHandlers: [] as { path: string; handler: (req: any, res: any) => void }[],
  deleteHandlers: [] as { path: string; handler: (req: any, res: any) => void }[],
  allHandlers: [] as { path: string; handler: (req: any, res: any) => void }[],
  match: (req: any, res: any) => {
    const { method, path } = req;
    const handlers = {
      post: router.postHandlers,
      get: router.getHandlers,
      put: router.putHandlers,
      delete: router.deleteHandlers,
      all: router.allHandlers,
    };
    const handler = handlers[method]?.find((h) => h.path === path);
    if (handler) {
      try {
        handler.handler(req, res);
      } catch (err) {
        console.error('Failed to handle request:', err);
        res.status(500).send('Internal Server Error');
      }
    } else {
      res.status(404).send('Not Found');
    }
  },
};

