export function render(container: HTMLElement) {
  container.innerHTML = `
    <div class="row">
      <div class="col">
        <h2>Article Editor</h2>
        <div class="form-group">
          <label>Title</label>
          <input id="titleInput" type="text" placeholder="Enter title" value="">
        </div>
        <div class="form-group">
          <label>Category</label>
          <select id="categorySelect">
            <option value="tech">Technology</option>
            <option value="design">Design</option>
            <option value="lifestyle">Lifestyle</option>
            <option value="entertainment">Entertainment</option>
          </select>
        </div>
        <div class="form-group">
          <label>Tags</label>
          <input id="tagsInput" type="text" placeholder="Separate tags with commas" value="">
        </div>
        <div class="form-group">
          <label>Content</label>
          <textarea id="contentEditor" placeholder="Write your article here..." style="min-height:300px"></textarea>
        </div>
        <div class="form-group">
          <button class="btn btn-primary" onclick="saveDraft()">Save Draft</button>
          <button class="btn" onclick="discardChanges()">Cancel</button>
        </div>
      </div>
    </div>
  `;

  const titleInput = document.getElementById('titleInput') as HTMLInputElement;
  const contentEditor = document.getElementById('contentEditor') as HTMLTextAreaElement;
  const categorySelect = document.getElementById('categorySelect') as HTMLSelectElement;
  const tagsInput = document.getElementById('tagsInput') as HTMLInputElement;

  function saveDraft() {
    const title = titleInput.value.trim();
    const content = contentEditor.value.trim();
    const category = categorySelect.value;
    const tags = tagsInput.value.split(',').map(t => t.trim()).filter(t => t.length > 0);

    if (title === '') { alert('Title is required'); return; }
    if (content === '') { alert('Content is required'); return; }

    // Save to localStorage
    try {
      const saved = localStorage.getItem('drafts');
      const drafts = saved ? JSON.parse(saved) : [];
      const draft = { title, content, category, tags, createdAt: new Date().toISOString() };
      drafts.push(draft);
      localStorage.setItem('drafts', JSON.stringify(drafts));
      alert('Draft saved!');
    } catch (e) { console.error(e); }
  }

  function discardChanges() {
    titleInput.value = '';
    contentEditor.value = '';
    categorySelect.value = 'tech';
    tagsInput.value = '';
    alert('Changes discarded');
  }
}

