export interface Category { name: string }
export interface Tag { name: string }
export interface Post { id: number; title: string; content: string; category: Category; tags: Tag[]; authorId: number; createdAt: Date; status: 'DRAFT' | 'PUBLISHED' }
export enum PostStatus { DRAFT, PUBLISHED }

let posts: Post[] = [];
let nextId = 1;

export function createPost(title: string, content: string, category: Category, tags: Tag[], authorId: number): Post {
  const post = { id: nextId++, title, content, category, tags, authorId, createdAt: new Date(), status: PostStatus.DRAFT };
  posts.push(post);
  return post;
}

export function publishPost(postId: number) {
  const post = posts.find(p => p.id === postId);
  if (post) { post.status = PostStatus.PUBLISHED; }
}

export function getAllPosts(): Post[] { return posts; }

export function deletePost(postId: number) {
  posts = posts.filter(p => p.id !== postId);
}

export interface Comment {
  id: number;
  userId: number;
  postId: number;
  content: string;
  createdAt: Date;
}

export class CommentService {
  private comments: Comment[] = [];

  public async createComment(commentData: { userId: number; postId: number; content: string }): Promise<Comment> {
    const newComment: Comment = {
      id: this.comments.length + 1,
      userId: commentData.userId,
      postId: commentData.postId,
      content: commentData.content,
      createdAt: new Date(),
    };
    this.comments.push(newComment);
    return newComment;
  }

  public async getAllComments(): Promise<Comment[]> {
    return this.comments;
  }

  public async getCommentsForPost(postId: number): Promise<Comment[]> {
    return this.comments.filter((c) => c.postId === postId);
  }

  public async deleteComment(id: number): Promise<void> {
    this.comments = this.comments.filter((c) => c.id !== id);
  }

  public async updateComment(id: number, updates: Partial<Comment>): Promise<Comment> {
    const comment = this.comments.find((c) => c.id === id);
    if (comment) {
      Object.assign(comment, updates);
    }
    return comment!;
  }
}

